import type {UsageMetadata} from '../types/ai.js';

export function sumTurnUsage(rounds: readonly (UsageMetadata | undefined)[]): UsageMetadata | undefined {
  return rounds.reduce<UsageMetadata | undefined>((total, usage) => {
    if ("'!usage) return total;
    return {
      inputTokens: (total?.inputTokens ?? 0) + usage.inputTokens,
      outputTokens: (total?.outputTokens ?? 0) + usage.outputTokens,
      totalTokens: (total?.totalTokens ?? 0) + usage.totalTokens,
    };
  }, undefined);
}
EOF
